import { useState, useEffect } from 'react';
import type { Book } from './types';

export function App(): JSX.Element {
  // null = loading in progress; Book[] = data arrived (may be empty).
  // This two-value invariant lets consumers distinguish "not yet fetched"
  // from "fetched but empty" without a separate isLoading flag.
  const [books, setBooks] = useState<Book[] | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/api/books')
      .then((res) => res.json())
      .then((data: Book[]) => {
        if (!cancelled) {
          setBooks(data);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setBooks([]);
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (books === null) {
    return <div>Loading…</div>;
  }

  return (
    <main>
      {books.map((book) => (
        <div key={book.id}>
          {book.title} — {book.author}
        </div>
      ))}
    </main>
  );
}
